from h import *
I=[]
I.append(R(6346471,"पेरूवियन चिकन सल्तादो","पेरूवियन सल्तादो पारंपरिक रूप से बीफ़ से बनता है, लेकिन यह ज़्यादा सेहतमंद संस्करण पारंपरिक स्वादों से समझौता किए बिना चिकन का उपयोग करता है। यह एक देहाती, झटपट और आरामदायक रेसिपी है जिसे भीड़ के लिए (या बचे हुए के लिए) आसानी से दोगुना किया जा सकता है।","4","1 कप",
["1 पाउंड चिकन टेंडरलॉइन","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","3 छोटा चम्मच जैतून का तेल (बाँटकर उपयोग करें)","1 पूरा लाल प्याज़ (पतला कटा हुआ)","2 (लगभग 1 पाउंड) बड़े टमाटर (डंठल निकाले, आधे कटे और स्लाइस में कटे हुए)","2 कली लहसुन (बारीक कटा हुआ)","2 छोटा चम्मच कम सोडियम वाला सोया सॉस","2 छोटा चम्मच रेड वाइन सिरका"],
["चिकन पर नमक और काली मिर्च छिड़कें। एक बड़ी नॉनस्टिक कड़ाही में 2 छोटा चम्मच तेल मध्यम-तेज़ आँच पर गरम करें। चिकन डालें और भूरा होने तक, लगभग 6 मिनट पकाएँ। प्लेट में निकाल लें।","प्याज़ और बचा हुआ 1 छोटा चम्मच तेल डालें और बीच-बीच में चलाते हुए नरम होने तक, लगभग 5 मिनट पकाएँ। टमाटर, लहसुन, सोया सॉस और सिरका डालें, और बीच-बीच में चलाते हुए टमाटर के नरम होने तक, लगभग 5 मिनट पकाएँ।","चिकन को वापस कड़ाही में डालें और अच्छी तरह गरम करें।"]))
I.append(R(6347356,"चिकन फ़्राइड फूलगोभी राइस","यह फूलगोभी चिकन फ़्राइड राइस एशियाई खाने की चाह होने पर एक बढ़िया कम कार्बोहाइड्रेट विकल्प है। फूलगोभी राइस और ताज़ी सब्ज़ियों के साथ, यह एक रंगीन और पौष्टिक रात का खाना है जिसे आसानी से बनाया जा सकता है।","4","1 कप",
["2 बड़े चम्मच एवोकाडो तेल","2 छोटा चम्मच ताज़ी अदरक (बारीक कटी हुई)","2 कली लहसुन (बारीक कटा हुआ)","1 कप मिली-जुली सब्ज़ियाँ (जैसे मटर, गाजर, मक्का, शिमला मिर्च; कटी हुई)","1 फूलगोभी (कद्दूकस की हुई या राइस के दानों जैसी)","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच तिल का तेल","1 कप बिना हड्डी, बिना त्वचा वाले चिकन ब्रेस्ट (पके हुए, छोटे टुकड़ों में कटे हुए)","1 बड़ा अंडा (फेंटा हुआ)","3 डंठल हरी प्याज़ (कटी हुई, ऊपर डालने के लिए)"],
["एक बड़ी नॉनस्टिक कड़ाही या वोक में 1 बड़ा चम्मच तेल मध्यम-तेज़ आँच पर गरम करें।","कटी हुई अदरक और लहसुन डालें, सुगंध आने तक लगभग 1 मिनट भूनें।","मिली-जुली सब्ज़ियाँ, फूलगोभी राइस, सोया सॉस और तिल का तेल कड़ाही में डालें और अच्छी तरह पकने और कुछ जगह भूरा होने तक 7-8 मिनट स्टिर-फ़्राई करें।","कटे हुए चिकन को कड़ाही में मिलाएँ।","मिश्रण को कड़ाही के एक तरफ़ करें और खाली जगह में बचा हुआ 1 बड़ा चम्मच तेल डालें। फेंटे हुए अंडे को खाली जगह में डालें। अंडे को बस पकने तक भुर्जी की तरह पकाएँ। अंडे को सब्ज़ी और चिकन के मिश्रण में मिलाएँ।","हरी प्याज़ से सजाकर समाप्त करें।"]))
I.append(R(6348205,"आलू और वसंत ऋतु की सब्ज़ियों के साथ मेमने के चॉप्स","मेमना ईस्टर के मौसम के लिए बढ़िया है और साल के किसी भी अन्य समय के लिए एक खास व्यंजन है। मेमने के लॉइन चॉप्स नरम, कम चर्बी वाला टुकड़ा हैं जो ग्रिल पर आसानी से पक जाते हैं। जब आप सामान्य चिकन और बीफ़ से ऊब जाएँ तो आज़माने के लिए ये एक अच्छा विकल्प हैं। इन्हें शतावरी (एस्पैरेगस) और गाजर जैसी वसंत ऋतु की सब्ज़ियों के साथ परोसें।","4","1-2 मेमने के चॉप्स + 1 आलू, 5 शतावरी की डंडियाँ और 2 गाजर",
["1 बड़ा चम्मच + 2 छोटा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर उपयोग करें)","2 कली लहसुन (बारीक कटा हुआ)","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","3 बड़े चम्मच ताज़ा रोज़मेरी (कटा हुआ, बाँटकर उपयोग करें)","1 पाउंड कम चर्बी वाले मेमने के लॉइन चॉप्स (चर्बी हटाई हुई)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 छोटे लाल आलू (चार भागों में कटे हुए, छिलके सहित)","8 मध्यम गाजर (आधी कटी हुई)","1 गुच्छा शतावरी (एस्पैरेगस) (लगभग 20 डंडियाँ, सिरे कटे हुए)"],
["1 बड़ा चम्मच जैतून का तेल, लहसुन, नमक, काली मिर्च और रोज़मेरी मिलाएँ। मेमने के चॉप्स पर पूरी तरह लेप लगाएँ और फ़्रिज में 2 घंटे मैरिनेट करें। ग्रिल करने से 30 मिनट पहले फ़्रिज से निकाल लें।","ओवन को 450°F पर पहले से गरम करें। शीट पैन पर कुकिंग स्प्रे करें।","आलू को एक कटोरे में रखें और 1 छोटा चम्मच जैतून का तेल और 2 बड़े चम्मच कटी रोज़मेरी के साथ मिलाएँ। उन्हें शीट पैन पर रखें और पहले से गरम ओवन के बीच में रखकर 10 मिनट भूनें।","उसी कटोरे में गाजर रखें और बचे तेल और रोज़मेरी के साथ मिलाएँ। इन्हें शतावरी के साथ आलू में डालें और 10 मिनट और भूनते रहें।","इस बीच, ग्रिल को पहले से गरम करें और मेमने के चॉप्स को सीधे ग्रिल पर रखें। 5 मिनट ग्रिल करें, फिर चॉप्स को पलटें और 3 – 5 मिनट और ग्रिल करते रहें। उनका आंतरिक तापमान 135°F तक पहुँचना चाहिए।"]))
I.append(R(6349071,"चिकन और वाइल्ड राइस सूप","वाइल्ड राइस एक साबुत अनाज है और सफ़ेद चावल से ज़्यादा सेहतमंद विकल्प है। यह सूप पेट भरने वाला है और सर्दियों के ठंडे दिन के लिए एकदम सही है।","9","लगभग 1 कप",
["2 छोटा चम्मच मार्जरीन (ट्रांस-फ़ैट-मुक्त)","1 मध्यम प्याज़ (छोटे टुकड़ों में कटा हुआ)","2 मध्यम गाजर (छोटे टुकड़ों में कटी हुई)","2 डंठल अजवाइन (सेलरी) (छोटे टुकड़ों में कटे हुए)","1 कप सफ़ेद (बटन) मशरूम (छोटे टुकड़ों में कटे हुए)","44 औंस कम सोडियम वाला चिकन शोरबा (बिना वसा वाला)","1 कप पानी (+ 1 बड़ा चम्मच ठंडा पानी, बाँटकर उपयोग करें)","1/4 छोटा चम्मच सूखा थाइम (सूखा)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक (वैकल्पिक)","1 बड़ा चम्मच कॉर्नस्टार्च","1 कप वाइल्ड राइस","2 कप पका हुआ चिकन (छोटे टुकड़ों में कटा हुआ)"],
["एक बड़े सूप के बर्तन में मार्जरीन को मध्यम-तेज़ आँच पर पिघलाएँ। प्याज़ डालें और 3 मिनट या पारदर्शी होने तक भूनें। गाजर, अजवाइन और मशरूम डालें और 5 मिनट भूनें।","चिकन शोरबा, पानी, थाइम, काली मिर्च और नमक डालें।","एक छोटे कप में कॉर्नस्टार्च और 1 बड़ा चम्मच ठंडा पानी मिलाएँ। इस मिश्रण को सूप में डालें।","उबाल आने दें और चावल मिलाएँ।","आँच कम करें, ढक दें और 45 मिनट धीमी आँच पर पकाएँ। पका हुआ चिकन डालें और अच्छी तरह मिलाएँ।"]))
I.append(R(6349432,"4-परत वाला भरा हुआ एवोकाडो","एवोकाडो हृदय के लिए लाभकारी मोनोअनसैचुरेटेड वसा से भरपूर होते हैं, और फ़ाइबर का कम कार्बोहाइड्रेट वाला स्रोत हैं। यहाँ हम आधे एवोकाडो के ऊपर काली बीन्स और सालसा डालकर एक सरल साउथवेस्ट नाश्ता या साइड डिश बना रहे हैं। आप अपनी पसंदीदा बोतलबंद सालसा इस्तेमाल कर सकते हैं, या घर पर बनी ऑलमोस्ट स्मूद सालसा की यह रेसिपी आज़माएँ।","4","1 एवोकाडो का आधा भाग",
["1/3 कप काली बीन्स (छनी और धुली हुई)","2 मध्यम एवोकाडो","4 बड़े चम्मच सादा बिना चर्बी वाला ग्रीक योगर्ट","4 बड़े चम्मच सालसा","4 छोटा चम्मच कम वसा वाला कद्दूकस किया चेडर या मैक्सिकन शैली का चीज़","1/4 छोटा चम्मच नमक","2 छोटा चम्मच ताज़ा नींबू का रस"],
["बीन्स को एक छोटे कटोरे में रखें। काँटे के पिछले हिस्से से लगभग चिकना होने तक मसलें।","एवोकाडो को आधा काटें और गुठली निकाल दें। हर एवोकाडो के बीच में 1 बड़ा चम्मच बीन्स, 1 बड़ा चम्मच ग्रीक योगर्ट और 1 बड़ा चम्मच सालसा की परत लगाएँ और ऊपर 1 छोटा चम्मच चीज़ छिड़कें। एवोकाडो पर नमक बराबर छिड़कें। हर एवोकाडो के आधे हिस्से को नींबू के 1 स्लाइस के साथ परोसें ताकि उसे व्यंजन पर निचोड़ा जा सके।"]))
I.append(R(6350887,"एवोकाडो और काली बीन्स सालसा","इस टेक्स-मेक्स से प्रेरित एवोकाडो और काली बीन्स सलाद से अपने सलाद में मसाला डालने के लिए तैयार हो जाएँ। रंगीन और ताज़ा, अगली बार जब आप मधुमेह के अनुकूल टैको ट्यूज़डे विकल्प चाहें तो यह सलाद बनाकर देखें।","6","3/4 कप",
["2 (15 औंस) डिब्बे काली बीन्स (कम सोडियम वाली, छनी और धुली हुई)","1 मध्यम एवोकाडो (छोटे टुकड़ों में कटा हुआ)","1 कप मक्का (पूरे दाने)","1 कप रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटे हुए)","1/2 कप लाल प्याज़ (बारीक कटा हुआ)","1/4 कप ताज़ी धनिया पत्ती (कटी हुई, सजाने के लिए और)","1 पूरी जलापेनो मिर्च (बीज निकाली हुई और बारीक कटी हुई)","2 बड़े चम्मच नींबू का रस","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च"],
["एक बड़े कटोरे में काली बीन्स, कटा एवोकाडो, मक्का के दाने, कटे टमाटर, बारीक कटा लाल प्याज़, कटी ताज़ी धनिया पत्ती और बारीक कटी जलापेनो मिलाएँ।","एक छोटे कटोरे में नींबू का रस, एक्स्ट्रा वर्जिन जैतून का तेल, पिसा जीरा, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद पर डालें और बराबर लेप के लिए धीरे से मिलाएँ।","स्वाद घुलने-मिलने के लिए सलाद को फ़्रिज में 10 मिनट मैरिनेट होने दें।","परोसने से पहले सलाद को एक बार फिर मिलाएँ। चाहें तो ऊपर ताज़ी धनिया पत्ती डालें।"]))
I.append(R(6352574,"अनानास और अखरोट के साथ कॉटेज चीज़","इस रेसिपी से अपने कॉटेज चीज़ को अगले स्तर पर ले जाएँ! अतिरिक्त ताज़गी के लिए ऊपर पुदीने की पत्तियाँ डालें।","2","1 ¼ कप",
["1 कप कॉटेज चीज़ (बिना वसा वाला)","1 कप अनानास (छोटे टुकड़ों में कटा हुआ)","2 बड़े चम्मच अखरोट (कटे हुए)"],
["एक कटोरे में कॉटेज चीज़, ताज़े अनानास के टुकड़े और कटे अखरोट मिलाएँ।","कॉटेज चीज़ के मिश्रण को परोसने के कटोरों में बाँटें। तुरंत परोसें और इस ताज़गी भरे और प्रोटीन से भरपूर व्यंजन का आनंद लें।"]))
I.append(R(6352737,"हमस डेविल्ड एग्स","पारंपरिक डेविल्ड एग्स का यह नया रूप आज़माएँ। कैलोरी, वसा और कोलेस्ट्रॉल कम करने के लिए अंडे की ज़र्दी की जगह चटपटे बीन्स का मिश्रण डालें। आपके मेहमान इनका उतना ही आनंद लेंगे!","8","2 अंडे के आधे भाग",
["8 बड़े अंडे (उबले और छिले हुए)","1 (14.5 औंस) डिब्बा छोले (काबुली चने) (छने और धुले हुए)","2 कली लहसुन","1 छोटा नींबू (छिलका कद्दूकस किया और रस निकाला हुआ)","1 बड़ा चम्मच जैतून का तेल","1/4 कप कम सोडियम वाला सब्ज़ी का शोरबा","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप सालसा","1 बड़ा चम्मच कटा हुआ ताज़ा अजमोद"],
["उबले अंडों को लंबाई में आधा काटें और ज़र्दी फेंक दें।","छोले, लहसुन, नींबू का छिलका, नींबू का रस, जैतून का तेल, शोरबा, नमक, काली मिर्च, सालसा और अजमोद को ब्लेंडर या फ़ूड प्रोसेसर में डालें। हमस के चिकना होने तक प्रोसेस करें।","हर अंडे के आधे भाग को एक ढेर लगे बड़े चम्मच हमस से भरें।"]))
I.append(R(6353740,"छोले की शक्शूका","छोले की शक्शूका क्लासिक शक्शूका का एक स्वादिष्ट और पौष्टिक रूप है। कुछ अतिरिक्त पौधों पर आधारित प्रोटीन के लिए, स्वाद से भरपूर इस नाश्ते में छोले डाले गए हैं।","4","कड़ाही का 1/4 भाग + छोटे पीटा का 1/4",
["1 बड़ा चम्मच जैतून का तेल","1 मध्यम पीला प्याज़ (कटा हुआ)","3 कली लहसुन","1 छोटा चम्मच जीरा","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच पिसा धनिया","1 (14 औंस) डिब्बा कटे हुए डिब्बाबंद टमाटर (बिना नमक मिलाए)","1 (14 औंस) डिब्बा डिब्बाबंद छोले (कम सोडियम वाले, छने और धुले हुए)","1/4 छोटा चम्मच नमक (बाँटकर)","1/2 छोटा चम्मच काली मिर्च","4 बड़े अंडे","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई, सजाने के लिए)","1 छोटा साबुत गेहूँ का पीटा (चार भागों में कटा हुआ)"],
["एक बड़ी कड़ाही में जैतून का तेल मध्यम आँच पर गरम करें।","कटा हुआ प्याज़ डालें और नरम होने तक, लगभग 5 मिनट पकाएँ।","बारीक कटा लहसुन डालें और 30 सेकंड और पकाएँ।","प्याज़ और लहसुन के ऊपर पिसा जीरा, पेपरिका और पिसा धनिया छिड़कें।","कटे टमाटर और छोले डालें। ½ छोटा चम्मच नमक और काली मिर्च से मसाला लगाएँ। मिश्रण के गाढ़ा होने तक 10–15 मिनट धीमी आँच पर पकाएँ।","मिश्रण में छोटे गड्ढे बनाएँ और हर गड्ढे में एक अंडा तोड़कर डालें। ½ छोटा चम्मच नमक छिड़कें।","कड़ाही को ढकें और 5–7 मिनट पकाएँ, या जब तक अंडे का सफ़ेद भाग जम न जाए लेकिन ज़र्दी अभी बहती रहे (अंडे की अपनी पसंद के अनुसार पकाने का समय बदलें)।","कटी ताज़ी तुलसी से सजाएँ और पीटा के स्लाइस के साथ परोसें।"]))
I.append(R(6354484,"चिकन के साथ पेपरकॉर्न पिस्ता सीज़र-शैली सलाद","यह मुख्य भोजन वाला सलाद लहसुन ब्रेड के साथ बहुत अच्छा लगता है। आप चिकन को ग्रिल करके और ड्रेसिंग पहले से बनाकर रख सकते हैं ताकि आप सप्ताह के दौरान इसे दोपहर के भोजन के लिए पैक कर सकें।","4","2 कप",
["4 बिना हड्डी और बिना त्वचा वाली चिकन थाई (हर एक 3 औंस की)","2 छोटा चम्मच कैनोला तेल","1/8 छोटा चम्मच कोशर नमक","1/3 कप हमस","3 बड़े चम्मच बिना चीनी की ग्रीन टी (ठंडी की हुई)","2 1/2 बड़े चम्मच परमेसन-रेगियानो चीज़ (कद्दूकस किया हुआ)","2 कली लहसुन (बड़ी कलियाँ)","1 बड़ा चम्मच डिजॉन सरसों","2 छोटा चम्मच वॉर्सेस्टरशायर सॉस","2 छोटा चम्मच नींबू का रस","1 1/4 छोटा चम्मच काली मिर्च के दाने (ताज़े कुटे हुए, बाँटकर)","8 कप मिले-जुले सलाद के पत्ते (8 औंस)","2 बड़े चम्मच पिस्ता (भुने हुए, छिले हुए, कटे हुए, हल्के नमकीन)"],
["ग्रिल या ग्रिल पैन को पहले से गरम करें। चिकन पर तेल लगाएँ और नमक छिड़कें। सीधी मध्यम आँच पर पूरी तरह पकने और ग्रिल के निशान बनने तक ग्रिल करें। एक तरफ़ रख दें।","हमस, चाय, चीज़, लहसुन, सरसों, वॉर्सेस्टरशायर सॉस, नींबू का रस और 1 छोटा चम्मच काली मिर्च के दाने ब्लेंडर में डालें। ढककर प्यूरी बना लें।","परोसने के लिए तैयार होने पर, एक बड़े मिक्सिंग कटोरे में ड्रेसिंग को सलाद के पत्तों के साथ मिलाएँ। 4 अलग कटोरों या प्लेटों में डालें, ऊपर ग्रिल्ड चिकन रखें, पिस्ता और बची 1/4 छोटा चम्मच काली मिर्च के दाने छिड़कें, और परोसें।"]))
I.append(R(6356142,"शकरकंद टॉपिंग वाले मीटलोफ़ मफ़िन","यह सेहतमंद भोजन बेहद आसान और स्वादिष्ट है। यह कहने की ज़रूरत नहीं - छोटे मफ़िन आकार के कारण यह बड़े मीटलोफ़ की तुलना में जल्दी बेक हो जाता है।","12","1 मफ़िन",
["2 मध्यम शकरकंद","1 बड़ा चम्मच मार्जरीन (ट्रांस-फ़ैट-मुक्त)","20 औंस कम चर्बी वाला टर्की का कीमा","1 बड़ा अंडा (हल्का फेंटा हुआ)","1 बड़ा चम्मच लाल मिर्च पाउडर","1/4 छोटा चम्मच काली मिर्च","1 छोटा चम्मच लहसुन पाउडर","1/3 कप प्याज़ (बारीक कटा हुआ)","1/2 कप कॉर्नमील या ओट्स (अगर ग्लूटेन-फ़्री आहार ले रहे हैं तो ग्लूटेन-फ़्री ओट्स)","2 बड़े चम्मच केचप"],
["ओवन को 425 डिग्री F पर पहले से गरम करें। मफ़िन पैन में मफ़िन पेपर लगाएँ।","आलू को साफ़ करें और काँटे से कई बार छेद दें। आलू को ओवन में 20 मिनट बेक करें। आलू को ओवन से निकालें और अतिरिक्त 5 मिनट या नरम होने तक माइक्रोवेव करें। आलू के छिलके उतारें और आलू को एक मध्यम कटोरे में रखें। पोटैटो मैशर से मसलें और मार्जरीन फेंटकर मिलाएँ। अच्छी तरह मिलाएँ।","एक मध्यम कटोरे में मीटलोफ़ की सामग्री को मिलाएँ।","लगभग 1/4 कप मीटलोफ़ का मिश्रण हर लगे हुए मफ़िन कप में डालें। 25 मिनट बेक करें।","हर पके हुए मीटलोफ़ मफ़िन के ऊपर एक चम्मच शकरकंद डालें।"]))
I.append(R(6356826,"पालक और पाइन नट क्विनोआ","यह पोषण से भरपूर साइड डिश मछली, चिकन या पोर्क के साथ बहुत अच्छी लगेगी।","6","1/2 कप",
["1 कप क्विनोआ (सूखा)","2 कप कम सोडियम वाला सब्ज़ी का शोरबा","1 बड़ा चम्मच जैतून का तेल","2 कली लहसुन (बारीक कटा हुआ)","6 औंस बेबी पालक","1/4 कप पाइन नट्स (भुने हुए)","1/8 छोटा चम्मच काली मिर्च","2 बड़े चम्मच परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ)"],
["क्विनोआ को चिकन शोरबे के साथ पैकेट के निर्देशों के अनुसार पकाएँ।","सौते पैन में जैतून का तेल मध्यम-तेज़ आँच पर गरम करें। लहसुन डालें और 30 सेकंड भूनें। पालक डालें और लगभग 5 मिनट भूनें।","पके हुए क्विनोआ को एक मध्यम कटोरे में डालें; पालक और बाकी सामग्री डालें और अच्छी तरह मिलाएँ।"]))
I.append(R(6357497,"स्मोक्ड सैल्मन और ग्रीक योगर्ट ऑमलेट","यह शानदार ऑमलेट मुलायम स्मोक्ड सैल्मन को मलाईदार ग्रीक योगर्ट और ताज़े सोआ के साथ जोड़ता है, जो दिन की प्रोटीन से भरपूर और संतोषजनक शुरुआत है। अपने रक्त ग्लूकोज़ (ब्लड शुगर) पर नज़र रखने वालों के लिए यह एक समझदार नाश्ता विकल्प है, क्योंकि इसमें कार्बोहाइड्रेट कम और प्रोटीन संतुलित है।","4","1 ऑमलेट",
["4 बड़े अंडे","1/2 कप अंडे का सफ़ेद भाग","1/4 कप 1% दूध","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच जैतून का तेल","2 औंस ठंडा स्मोक्ड सैल्मन (कम सोडियम वाला, कटा हुआ)","1/4 कप सादा बिना चर्बी वाला ग्रीक योगर्ट","1 बड़ा चम्मच ताज़ा सोआ (कटा हुआ, सजाने के लिए और)","1/2 छोटा लाल प्याज़ (पतला कटा हुआ)"],
["एक कटोरे में अंडे, अंडे का सफ़ेद भाग, दूध, नमक और काली मिर्च को चिकना होने तक फेंटें।","नॉनस्टिक कड़ाही में जैतून का तेल मध्यम-धीमी आँच पर गरम करें। अंडे के मिश्रण का ¼ भाग कड़ाही में डालें, तली को ढकने के लिए घुमाएँ। किनारों के जमना शुरू होने तक, लगभग 2 मिनट पकाएँ।","ऑमलेट के एक तरफ़ ¼ स्मोक्ड सैल्मन, एक चम्मच ग्रीक योगर्ट, ताज़ा सोआ और लाल प्याज़ डालें।","ऑमलेट को सावधानी से भरावन के ऊपर मोड़ें और गरम करने के लिए 30 सेकंड पकाएँ।","प्लेट में निकालें और बाकी सामग्री के साथ यही दोहराएँ।"]))
I.append(R(6358049,"बजट के अनुकूल एशियाई टर्की बर्गर","अपने बर्गर में मसाला डालने का तरीका ढूँढ रहे हैं? तो यह रेसिपी बिल्कुल आपके लिए है! इस रेसिपी में इस्तेमाल सॉस जैसे ऑयस्टर सॉस, थाई चिली गार्लिक और श्रीराचा ज़्यादातर किराने की दुकानों के अंतरराष्ट्रीय खाद्य वाले हिस्से में मिल सकते हैं।","6","1 बर्गर",
["1 बड़ा चम्मच ऑयस्टर सॉस (अगर ऑयस्टर सॉस न मिले, तो 1 बड़ा चम्मच कम सोडियम वाला सोया सॉस इस्तेमाल करें)","20 औंस कम चर्बी वाला टर्की का कीमा (93% वसा-रहित)","2 डंठल हरी प्याज़ (बारीक कटी हुई, सफ़ेद और हरा भाग)","1 कली लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच थाई शैली का चिली गार्लिक पेस्ट","1 छोटा चम्मच तिल का तेल","1 बड़ा चम्मच ताज़ी अदरक (कद्दूकस की हुई)","1 बड़ा चम्मच नींबू का रस","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च","1/3 कप सादा दही (बिना वसा वाला)","1 छोटा चम्मच श्रीराचा","12 पत्ते बिब या बोस्टन लेट्यूस","18 स्लाइस खीरा"],
["इनडोर या आउटडोर ग्रिल तैयार करें।","एक बड़े कटोरे में टर्की का कीमा, हरी प्याज़, लहसुन, ऑयस्टर सॉस, चिली गार्लिक पेस्ट, तिल का तेल, कद्दूकस की अदरक, नींबू का रस, नमक (वैकल्पिक) और काली मिर्च मिलाएँ। 6 टिक्कियाँ बनाएँ और ग्रिल करने के लिए तैयार होने तक, कम से कम 15 मिनट फ़्रिज में रखें।","बर्गर को हर तरफ़ 5-7 मिनट या बर्गर का आंतरिक तापमान 165 डिग्री F होने तक ग्रिल करें।","बर्गर जोड़ने के लिए, एक छोटे कटोरे में दही और श्रीराचा मिलाएँ। हर बर्गर को लेट्यूस के दो पत्तों के बीच, थोड़े कम 1 बड़ा चम्मच दही के मिश्रण और 3 खीरे के स्लाइस के साथ परत में लगाएँ।"]))
